    for k in range(n-1):
        if A[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j])
                if k > 0:
                    A[i][j] //= A[k-1][k-1]
            A[i][k] = 0
