import random

def greedy(meetings):
    meetings=sorted(meetings,key=lambda x:(x[1],x[0]))
    cnt=0
    cur=-10**9
    for s,e in meetings:
        if s>=cur:
            cnt+=1
            cur=e
    return cnt

def optimal(meetings):
    # brute force via DP for small n
    best=0
    n=len(meetings)
    from itertools import combinations
    for r in range(n+1):
        for combo in combinations(meetings,r):
            combo=sorted(combo,key=lambda x:x[0])
            ok=True
            for i in range(len(combo)-1):
                if combo[i][1]>combo[i+1][0]:
                    ok=False;break
            if ok:
                best=max(best,len(combo))
    return best

for _ in range(1000):
    m=random.randint(0,6)
    meetings=[[random.randint(0,10),random.randint(0,10)] for __ in range(m)]
    meetings=[[min(a,b),max(a,b)] for a,b in meetings]
    if greedy(meetings)!=optimal(meetings):
        print('found mismatch', meetings, greedy(meetings), optimal(meetings))
        break
else:
    print('no mismatch')

