def solve(n,b):
    if b < 2 or b > 36:
        raise ValueError('base out of range')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

def solve(path):
    """Simplify an absolute Unix-style path.
    Args:
        path (str): absolute path starting with '/'.
    Returns:
        str: simplified canonical path.
    """
    # Split by '/' and process components
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # empty part due to // or current directory, skip
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if at root, stay root (do nothing)
        else:
            stack.append(part)
    # Construct result
    if not stack:
        return '/'
    return '/' + '/'.join(stack)

