def solve(s: str) -> int:
    """Return the length of the longest substring without repeating characters.

    Uses a sliding window and a dictionary that records the most recent index of each character.
    """
    last_index = {}
    start = 0  # start index of current window
    max_len = 0
    for i, ch in enumerate(s):
        # If character was seen and is inside the current window, move start
        if ch in last_index and last_index[ch] >= start:
            start = last_index[ch] + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

