def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero as per problem statement.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Python's int division truncates toward zero when using int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

