def solve(matrix):
    """Determinant of integer matrix using Bareiss algorithm.
    Returns 1 for empty matrix. If matrix is not square, returns 0.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square
    for row in matrix:
        if len(row) != n:
            return 0
    a = [list(row) for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        if a[k][k] == 0:
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                num = a[i][j] * a[k][k] - a[i][k] * a[k][j]
                den = a[k - 1][k - 1] if k > 0 else 1
                a[i][j] = num // den
            a[i][k] = 0
    return det_sign * a[n - 1][n - 1]

def solve(year, month, day):
    # Zeller's Congruence for Gregorian calendar
    if month < 3:
        month += 12
        year -= 1
    K = year % 100
    J = year // 100
    h = (day + (13*(month+1))//5 + K + K//4 + J//4 + 5*J) % 7
    mapping = {0:'Saturday',1:'Sunday',2:'Monday',3:'Tuesday',4:'Wednesday',5:'Thursday',6:'Friday'}
    return mapping[h]

